"""Run the completeness diagnostic on categorical states generated by the prior."""

import argparse
import hashlib
import json
from pathlib import Path

import numpy as np
from filelock import FileLock
from tqdm.auto import tqdm

from analysis.analysis_prior import generate as prior_generation
from analysis.analysis_prior.config import CACHE_FORMAT_VERSION, PriorSpec, pinned
from rebuttal import completeness_scm as baseline


category_caps = (2, 4)
checkpoint_dir = baseline.checkpoint_dir.with_name("completeness_scm_cat")
CHECKPOINT_VERSION = 1
MATRIX_FIELDS = ("p_u_given_z", "p_w_given_u", "sv_z", "sv_w")
NULL_REPLICATES = 128


def categorical_spec(dim, cap, *, n_samples, n_scms, seed):
    return PriorSpec(
        name="rebuttal_completeness_scm_cat",
        n_datasets=n_scms,
        seq_len=n_samples,
        mc_cate=1,
        seed=seed,
        min_dim_X=0,
        max_dim_X=0,
        min_dim_U=dim,
        max_dim_U=dim,
        min_dim_W=dim,
        max_dim_W=dim,
        min_dim_Z=dim,
        max_dim_Z=dim,
        fixed_hp_overrides={
            "corrupt_U": True,
            "enforce_categorical_completeness": True,
            "max_categories": cap,
            "proxy_cat_cover_prob": 1.0,
        },
        sampled_hp_overrides={"cat_col_prob": pinned(1.0)},
    )


def joint_categories(block, cap):
    """Code the observed joint states, preserving one state per distinct tuple."""
    if any(np.unique(column).size > cap for column in block.T):
        raise ValueError(f"Generated column exceeds the category cap of {cap}")
    states, codes = np.unique(block, axis=0, return_inverse=True)
    return codes.ravel(), len(states)


def analyze_scm(spec, index):
    sample = prior_generation.generate(spec, indices=[index], progress=False)[0]
    dim = spec.min_dim_U
    cap = spec.fixed_hp_overrides["max_categories"]
    if (sample.U.shape[1], sample.W.shape[1], sample.Z.shape[1]) != (dim,) * 3:
        print(f"d={dim}, k={cap}, SCM {index}: skipped after constant-column filtering")
        return []

    (u, n_u), (w, n_w), (z, n_z) = (
        joint_categories(block, cap) for block in (sample.U, sample.W, sample.Z)
    )
    rows = []
    for arm in (0, 1):
        mask = sample.A == arm
        p_u_given_z = baseline.probability_matrix(z[mask], u[mask], n_z, n_u)
        p_w_given_u = baseline.probability_matrix(u[mask], w[mask], n_u, n_w)
        rows.append(
            {
                "dim": dim,
                "k": cap,
                "scm": index,
                "arm": arm,
                "n_rows": int(mask.sum()),
                "n_u": n_u,
                "n_w": n_w,
                "n_z": n_z,
                "p_u_given_z": p_u_given_z,
                "p_w_given_u": p_w_given_u,
                "sv_z": baseline.latent_spectrum(p_u_given_z, n_u),
                "sv_w": baseline.latent_spectrum(p_w_given_u, n_u),
            }
        )
    return rows


def run_sweep(*, n_samples, n_scms, category_caps, dimensions, seed):
    """Generate or resume one set of SCMs per dimension and category cap."""
    if not category_caps or min(category_caps) < 2:
        raise ValueError("category caps must be at least 2")
    if not dimensions or min(dimensions) < 1:
        raise ValueError("dimensions must be positive")
    specs = {
        (dim, cap): categorical_spec(
            dim, cap, n_samples=n_samples, n_scms=n_scms, seed=seed
        )
        for dim in dimensions
        for cap in category_caps
    }
    config = {
        "version": CHECKPOINT_VERSION,
        "prior_version": CACHE_FORMAT_VERSION,
        "prior_specs": [spec.to_dict() for spec in specs.values()],
        "category_caps": list(category_caps),
    }
    config_id = hashlib.sha256(json.dumps(config, sort_keys=True).encode()).hexdigest()[
        :16
    ]
    checkpoint_dir.mkdir(parents=True, exist_ok=True)
    path = checkpoint_dir / f"{config_id}.json"

    with FileLock(path.with_suffix(".lock")):
        if path.exists():
            checkpoint = json.loads(path.read_text(encoding="utf-8"))
            if checkpoint["config"] != config:
                raise ValueError(f"Checkpoint configuration mismatch in {path}")
        else:
            checkpoint = {"config": config, "completed": [], "results": []}

        completed = {tuple(key) for key in checkpoint["completed"]}
        total = len(specs) * n_scms
        print(f"Checkpoint {path} ({len(completed)}/{total} SCMs done)", flush=True)
        pending = [
            (dim, cap, index)
            for dim, cap in specs
            for index in range(n_scms)
            if (dim, cap, index) not in completed
        ]
        for dim, cap, index in tqdm(
            pending, desc="SCMs", initial=len(completed), total=total, disable=None
        ):
            checkpoint["results"].extend(analyze_scm(specs[dim, cap], index))
            checkpoint["completed"].append((dim, cap, index))
            baseline.save_checkpoint(path, checkpoint)

    for row in checkpoint["results"]:
        for field in MATRIX_FIELDS:
            if row[field] is not None:
                row[field] = np.asarray(row[field])
    return checkpoint["results"], path


def report_support(results, dimensions, caps):
    """Report joint support sizes and how often conditioning states go unobserved."""
    for dim in dimensions:
        for cap in caps:
            rows = [row for row in results if row["dim"] == dim and row["k"] == cap]
            if not rows:
                print(f"d={dim}, k={cap}: no SCMs with all columns retained")
                continue
            supports = []
            for block in ("u", "w", "z"):
                sizes = [row[f"n_{block}"] for row in rows]
                supports.append(f"{block.upper()} {min(sizes)}–{max(sizes)}")
            missing_z = sum(row["p_u_given_z"] is None for row in rows)
            missing_u = sum(row["p_w_given_u"] is None for row in rows)
            print(
                f"d={dim}, k={cap}: joint states {', '.join(supports)}. "
                f"Arms with empty conditioning rows (out of {len(rows)}): "
                f"Z {missing_z}, U {missing_u}"
            )


def rank_one_null(shape, n_samples, n_u, rng):
    """Sample smallest singular values under a uniform, independent outcome."""
    if min(shape) < n_u:
        return np.zeros(NULL_REPLICATES)

    n_conditioning, n_outcomes = shape
    quotient, remainder = divmod(n_samples, n_conditioning)
    row_counts = np.full(n_conditioning, quotient)
    row_counts[:remainder] += 1
    probabilities = np.full(n_outcomes, 1 / n_outcomes)

    smallest = np.empty(NULL_REPLICATES)
    for draw in range(NULL_REPLICATES):
        counts = rng.multinomial(row_counts, probabilities)
        matrix = counts / row_counts[:, None]
        smallest[draw] = baseline.latent_spectrum(matrix, n_u)[-1]
    return smallest


def plot_results(results, n_scms, dimensions, caps):
    from matplotlib.lines import Line2D

    # Keep repeated zeros so their ECDF jump is drawn at zero.
    fig = baseline.plot_results(results, n_scms, dimensions, caps, compress_ecdf=False)
    by_arm = {(r["dim"], r["k"], r["scm"], r["arm"]): r for r in results}
    panels = zip(
        (fig.axes[: len(caps)], fig.axes[len(caps) :]), MATRIX_FIELDS[:2], strict=True
    )
    for proxy_index, (axes, field) in enumerate(panels):
        for ax, cap in zip(axes, caps, strict=True):
            for color_index, dim in enumerate(dimensions):
                rng = np.random.default_rng([proxy_index, cap, dim])
                null_values = []
                for scm in range(n_scms):
                    arm_0 = by_arm.get((dim, cap, scm, 0), {})
                    arm_1 = by_arm.get((dim, cap, scm, 1), {})
                    if arm_0.get(field) is None or arm_1.get(field) is None:
                        continue
                    arm_nulls = [
                        rank_one_null(
                            np.shape(row[field]), row["n_rows"], row["n_u"], rng
                        )
                        for row in (arm_0, arm_1)
                    ]
                    null_values.append(np.minimum(*arm_nulls))
                if null_values:
                    ax.ecdf(
                        np.concatenate(null_values),
                        color=f"C{color_index}",
                        linestyle="--",
                        linewidth=1,
                        zorder=3,
                    )

    for ax, cap in zip(fig.axes[: len(caps)], caps, strict=True):
        ax.set_title(f"$k={cap}$ per column", fontsize=11)
    handles, labels = fig.axes[0].get_legend_handles_labels()
    handles.append(Line2D([], [], color="black", linestyle="--"))
    labels.append("Rank-one null")
    fig.legends[0].remove()
    fig.legend(
        handles, labels, loc="outside upper center", ncols=len(labels), frameon=False
    )
    return fig


def main():
    parser = argparse.ArgumentParser(description=__doc__)
    parser.add_argument(
        "--n-samples",
        type=int,
        default=baseline.n_samples,
        help="Rows per SCM across both arms",
    )
    parser.add_argument(
        "--n-scms", type=int, default=baseline.n_scms, help="SCMs per dimension and cap"
    )
    parser.add_argument(
        "--category-caps",
        "--bin-counts",
        type=baseline.comma_separated_ints,
        help="Comma-separated per-column category caps (defaults to 2,4 or the saved caps)",
    )
    parser.add_argument(
        "--dimensions",
        type=baseline.comma_separated_ints,
        default=baseline.dimensions,
        help="Comma-separated common dimensions of U, W and Z",
    )
    parser.add_argument("--seed", type=int, default=baseline.seed, help="Prior seed")
    parser.add_argument(
        "--plot-checkpoint", type=Path, help="Plot a saved categorical checkpoint"
    )
    parser.add_argument(
        "--output",
        type=Path,
        help="Figure path (defaults to a PNG next to the checkpoint)",
    )
    args = parser.parse_args()

    if args.plot_checkpoint is not None:
        path = args.plot_checkpoint
        checkpoint = json.loads(path.read_text(encoding="utf-8"))
        config = checkpoint["config"]
        if "category_caps" not in config:
            parser.error(f"{path} is not a categorical completeness checkpoint")
        saved_caps = tuple(config["category_caps"])
        caps = args.category_caps or saved_caps
        unavailable = sorted(set(caps) - set(saved_caps))
        if unavailable:
            parser.error(f"category caps {unavailable} are absent from {path}")
        specs = config["prior_specs"]
        dimensions = tuple(dict.fromkeys(spec["min_dim_U"] for spec in specs))
        n_scms = specs[0]["n_datasets"]
        results = checkpoint["results"]
        print(
            f"Plotting {path} ({len(checkpoint['completed'])}/{len(specs) * n_scms} SCMs done)"
        )
    else:
        caps = saved_caps = args.category_caps or category_caps
        dimensions = args.dimensions
        n_scms = args.n_scms
        if args.n_samples < 2 or n_scms < 1:
            parser.error("require at least two rows and one SCM")
        if min(caps) < 2 or min(dimensions) < 1:
            parser.error(
                "category caps must be at least 2 and dimensions must be positive"
            )
        results, path = run_sweep(
            n_samples=args.n_samples,
            n_scms=n_scms,
            category_caps=caps,
            dimensions=dimensions,
            seed=args.seed,
        )

    import matplotlib

    matplotlib.use("Agg")
    report_support(results, dimensions, caps)
    fig = plot_results(results, n_scms, dimensions, caps)
    stem = path.stem
    if caps != saved_caps:
        stem += "_k" + "-".join(map(str, caps))
    output = args.output or path.with_name(f"{stem}.png")
    output.parent.mkdir(parents=True, exist_ok=True)
    fig.savefig(output, dpi=360)
    print(f"Wrote {output}")


if __name__ == "__main__":
    main()
